import SwiftUI

/// Third-party licences, read from `Acknowledgements.json` (generated by `scripts/generate-acknowledgements.py`).
struct Acknowledgements: Decodable {
    struct Native: Decodable, Hashable { let name: String; let license: String; let role: String }
    struct Crate: Decodable, Hashable { let name: String; let version: String; let license: String }
    let native: [Native]
    let rust: [Crate]

    static func load(bundle: Bundle = .main) -> Acknowledgements? {
        guard let url = bundle.url(forResource: "Acknowledgements", withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(Acknowledgements.self, from: data)
    }
}

/// Settings > About: version, app licence and acknowledgements (third-party licences).
struct AboutSettingsTab: View {
    @Environment(AppModel.self) private var model
    @State private var acknowledgements = Acknowledgements.load()

    private var version: String {
        let info = Bundle.main.infoDictionary
        return "\(info?["CFBundleShortVersionString"] as? String ?? "?") (\(info?["CFBundleVersion"] as? String ?? "?"))"
    }

    var body: some View {
        Form {
            Section {
                HStack(spacing: 14) {
                    Image(nsImage: NSApp.applicationIconImage)
                        .resizable()
                        .frame(width: 56, height: 56)
                    VStack(alignment: .leading, spacing: 3) {
                        Text("Playfin").font(.title2.bold())
                        Text("A native macOS client for Jellyfin").foregroundStyle(.secondary)
                        Text("Version \(version) · core \(model.rustCoreVersion)").font(.caption).foregroundStyle(.secondary)
                    }
                }
                Text("Playfin is free software (MPL-2.0 licence). It is not an official product of the Jellyfin project.")
                    .font(.callout).foregroundStyle(.secondary)
            }

            Section("Acknowledgements — bundled libraries") {
                if let acknowledgements {
                    ForEach(acknowledgements.native, id: \.self) { item in
                        LabeledContent {
                            Text(item.license).font(.caption.monospaced()).foregroundStyle(.secondary)
                        } label: {
                            VStack(alignment: .leading, spacing: 1) {
                                Text(item.name)
                                Text(item.role).font(.caption).foregroundStyle(.secondary)
                            }
                        }
                    }
                    Text("mpv and FFmpeg are used in their LGPL build and linked dynamically.")
                        .font(.caption).foregroundStyle(.secondary)
                } else {
                    Text("List unavailable.").foregroundStyle(.secondary)
                }
            }

            if let crates = acknowledgements?.rust, !crates.isEmpty {
                Section("Acknowledgements — Rust libraries of the core (\(crates.count))") {
                    DisclosureGroup("Show the list") {
                        ForEach(crates, id: \.self) { crate in
                            LabeledContent("\(crate.name) \(crate.version)") {
                                Text(crate.license).font(.caption.monospaced()).foregroundStyle(.secondary)
                            }
                        }
                    }
                }
            }
        }
        .formStyle(.grouped)
    }
}
